sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Sys_ids of Maker and Checker users
    // var makerUser = '380f8c683be3e610f13f5fea26e45a3b'; // Maker
    //  var checkerUser = 'fb1010e83be3e610f13f5fea26e45ad3'; // Checker

    // Run only if screening fields changed
    if (!(current.pep.changes() || current.sanctions.changes() || current.adverse_news_screening.changes())) {
        return;
    }

    var pep = current.pep;
    var sanc = current.sanctions;
    var adv = current.adverse_news_screening;

    //var assignUser, caseState;

    // Condition 1: If any YES → Maker
    if (pep == 'yes' || sanc == 'yes' || adv == 'yes') {
        // assignUser = makerUser;
        caseState = '150';

        // Condition 2: If all NO → Checker
    } else if (pep == 'no' && sanc == 'no' && adv == 'no') {
        //assignUser = checkerUser;
        caseState = '320';

        // Condition 3: Any empty (or mix of NO + empty) → Do nothing
    } else {
        return;
    }

    // --- Update Case ---
    var caseGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases');
    caseGR.addQuery('entity.email_id', current.fcc_kyc_case.entity.email_id);
    caseGR.addQuery('case_type', 'periodic_kyc_case');
    caseGR.addQuery('state', 'NOT IN', '300,350,400,450');
    caseGR.query();
    if (caseGR.next()) {
        if (gs.nil(caseGR.assigned_to)) { // Only update if unassigned
            caseGR.state = caseState;
            //caseGR.assigned_to = assignUser;
            caseGR.update();
        }

        // --- Update Tasks ---
        var taskGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_tasks');
        taskGR.addQuery('kyc_case', caseGR.sys_id);
        taskGR.addQuery('type', 'adverse_news_screening');
        taskGR.query();

        while (taskGR.next()) {
            if (gs.nil(taskGR.assigned_to)) {
                if (caseGR.state == '150') // Only update if unassigned
                {
                    taskGR.assigned_to = caseGR.assigned_to.sys_id;
                }
				else
				{
					taskGR.state='4';
				}
                taskGR.update();
            }
        }
    }

})(current, previous);
